namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (!TryCalculateOrderQuantity(item, season, out int orderQty))
                continue;

            bool placed = supplier.PlaceOrder(item.Sku, orderQty);
            plan.Add(FormatPlanEntry(item, orderQty, placed));
        }

        return plan;
    }

    private static bool TryCalculateOrderQuantity(StockItem item, int season, out int orderQty)
    {
        orderQty = 0;
        if (item.OnHand < 0)
            return false;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return false;

        int deficit = item.ReorderPoint - available;
        orderQty = ApplySeasonalAdjustment(CalculateBaseOrderQuantity(deficit), season);

        return orderQty > 0 && !string.IsNullOrEmpty(item.Sku);
    }

    private static int CalculateBaseOrderQuantity(int deficit)
    {
        if (deficit <= 0)
            return 0;
        if (deficit < 10)
            return 10;
        if (deficit < 100)
            return deficit;

        return deficit + 50;
    }

    private static int ApplySeasonalAdjustment(int orderQty, int season)
    {
        if (season == 4 && orderQty > 0)
            return (int)(orderQty * 1.5);
        if (season == 1)
            return orderQty / 2;

        return orderQty;
    }

    private static string FormatPlanEntry(StockItem item, int orderQty, bool placed)
    {
        if (placed && orderQty > 200)
            return $"{item.Sku}:LARGE:{orderQty}";
        if (placed)
            return $"{item.Sku}:{orderQty}";

        return $"{item.Sku}:FAILED";
    }
}
